/** Returns the order total for a given subtotal. */
public BigDecimal total(BigDecimal subtotal) {
    return subtotal;
}

/** Returns unitPrice * qty with 5% off when qty >= 10, rounded once to 2 decimals HALF_UP. */
public BigDecimal bulkLineTotal(BigDecimal unitPrice, int qty) {
    if (unitPrice == null || unitPrice.compareTo(BigDecimal.ZERO) < 0 || qty <= 0) {
        throw new IllegalArgumentException("Invalid unitPrice or qty");
    }
    BigDecimal total = unitPrice.multiply(BigDecimal.valueOf(qty));
    if (qty >= 10) {
        total = total.multiply(new BigDecimal("0.95"));
    }
    return total.setScale(2, RoundingMode.HALF_UP);
}

